INSERT INTO model_alias_keys (alias_id, key_hash)
SELECT #{aliasId,jdbcType=BIGINT}, #{keyHash,jdbcType=VARCHAR}
WHERE NOT EXISTS (
    SELECT 1 FROM model_alias_keys
    WHERE alias_id = #{aliasId,jdbcType=BIGINT}
      AND key_hash = #{keyHash,jdbcType=VARCHAR})
